insert into public.site_settings (id, data) values (1, '{"brand":{"name":"Aurestride Digital","tagline":"Marketing e tecnologia para pequenos negócios","logo_url":"","description":"Marketing digital, criação de sites e sistemas web para pequenos negócios que querem crescer com mais presença, organização e profissionalismo."},"colors":{"background":"#0B1220","primary":"#086BFF","text":"#F8FAFC","muted":"#64748B"},"contact":{"whatsapp":"","whatsapp_message":"Olá! Vim pelo site da Aurestride Digital e gostaria de solicitar um orçamento.","plan_message":"Olá! Tenho interesse no {plano} da Aurestride Digital. Podemos conversar?","service_message":"Olá! Gostaria de um orçamento para: {servico}.","email":"","instagram":"","linkedin":"","tiktok":"","form_enabled":true},"seo":{"title":"Aurestride Digital — Marketing, sites e sistemas web para pequenos negócios","description":"Estratégia digital, gestão de redes sociais, criação de sites e sistemas web sob medida para pequenos negócios.","og_image":"","site_url":""},"hero":{"eyebrow":"Aurestride Digital","title":"Marketing e tecnologia potencializando o crescimento.","subtitle":"Unimos análise de dados, estratégia de marketing, posicionamento de marca, desenvolvimento de sites e sistemas automatizados para transformar negócios, otimizar processos e aumentar a produtividade.","image_url":"/images/hero-equipe.jpg","image_alt":"Maria e Lukas, da Aurestride Digital, em reunião","cta_primary":"Conheça nossos serviços","cta_secondary":"Solicitar orçamento","highlights":[{"title":"Marketing Digital","text":"Conteúdo, redes sociais e posicionamento"},{"title":"Sites","text":"Landing pages, institucionais e catálogos"},{"title":"Sistemas Web","text":"Gestão, automações e integrações"}]},"about":{"eyebrow":"Sobre nós","title":"Marketing e tecnologia trabalhando juntos","text":"A Aurestride Digital une estratégia de marketing e desenvolvimento web para oferecer soluções práticas e acessíveis a pequenos negócios. Cuidamos da presença digital da sua empresa e criamos as ferramentas que ajudam a organizar o dia a dia, para que você possa se concentrar em atender bem e crescer.","mission":"Ajudar pequenos negócios a crescer com comunicação clara e ferramentas digitais que simplificam a rotina.","vision":"Ser a parceira digital de referência para pequenos negócios que querem evoluir com profissionalismo.","values":["Transparência","Clareza no que é entregue","Proximidade com o cliente","Soluções práticas","Melhoria contínua"],"how_we_work":"Começamos entendendo o seu negócio, definimos juntos o escopo e o investimento, executamos com acompanhamento próximo e revisamos os resultados para planejar os próximos passos."},"sections":{"team_eyebrow":"Quem somos","team_title":"As pessoas por trás da Aurestride","team_subtitle":"Uma equipe enxuta, com atendimento direto de quem faz o trabalho.","marketing_eyebrow":"Marketing digital","marketing_title":"Presença digital com estratégia","marketing_subtitle":"Planejamento, criação e acompanhamento para que suas redes sociais trabalhem a favor do seu negócio.","web_eyebrow":"Criação de sites","web_title":"Sites que apresentam e vendem","web_subtitle":"Páginas rápidas, responsivas e pensadas para transformar visitantes em contatos.","systems_eyebrow":"Sistemas web e automações","systems_title":"Tecnologia sob medida para a sua rotina","systems_subtitle":"Cada sistema personalizado começa com um levantamento de requisitos. Entendemos o seu processo antes de propor uma solução e um orçamento específico.","plans_eyebrow":"Planos de marketing","plans_title":"Escolha o plano ideal para o seu momento","plans_subtitle":"Valores mensais de referência. Os vídeos curtos fazem parte da quantidade total de conteúdos de cada plano.","plans_disclaimer":"Não estão incluídos, salvo previsão expressa em proposta: captação presencial de fotos e vídeos, deslocamento, anúncios pagos, verba de mídia e ferramentas de terceiros.","web_pricing_eyebrow":"Investimento","web_pricing_title":"Desenvolvimento web","web_pricing_disclaimer":"Valores de referência. O valor final depende do escopo, funcionalidades, integrações, prazo e requisitos de cada projeto.","portfolio_eyebrow":"Portfólio","portfolio_title":"Projetos e estudos de caso","portfolio_subtitle":"Conheça alguns trabalhos desenvolvidos pela Aurestride.","portfolio_empty":"Novos projetos serão publicados em breve.","process_eyebrow":"Como funciona","process_title":"Um processo simples e transparente","faq_eyebrow":"Dúvidas","faq_title":"Perguntas frequentes","contact_eyebrow":"Contato","contact_title":"Vamos conversar sobre o seu negócio?","contact_text":"Conte o que você precisa e retornamos com uma proposta clara, com escopo e investimento definidos."},"layout":{"sections":[{"id":"about","visible":true},{"id":"team","visible":true},{"id":"marketing","visible":true},{"id":"sites","visible":true},{"id":"systems","visible":true},{"id":"plans","visible":true},{"id":"web_pricing","visible":true},{"id":"portfolio","visible":true},{"id":"process","visible":true},{"id":"faq","visible":true},{"id":"contact","visible":true}]},"footer":{"text":"Marketing digital, sites e sistemas web para pequenos negócios.","copyright":"Aurestride Digital. Todos os direitos reservados."},"privacy":{"enabled":true,"content":"Esta política descreve como a Aurestride Digital trata os dados enviados pelo formulário de contato deste site.\n\nDados coletados: nome, e-mail, telefone, empresa e a mensagem que você escrever. Também registramos um identificador anônimo do endereço de acesso para evitar envios abusivos.\n\nFinalidade: usamos esses dados apenas para responder ao seu contato e elaborar propostas comerciais.\n\nCompartilhamento: não vendemos nem compartilhamos seus dados com terceiros para fins de marketing. Os dados ficam armazenados em provedor de banco de dados com acesso restrito à equipe.\n\nSeus direitos: você pode solicitar a consulta, correção ou exclusão dos seus dados a qualquer momento pelos nossos canais de contato.\n\n[Texto provisório — revisar com orientação jurídica antes da publicação definitiva.]"}}'::jsonb)
