insert into public.portfolio_projects (slug, title, client, category, summary, challenge, solution, deliverables, results, external_url, status, sort_order) values ('ambrozio-car', 'Ambrozio Car', 'Ambrozio Car', 'sistema', '[Rascunho] Projeto-piloto da Aurestride. Publicar somente com autorização do cliente.', '[Rascunho — preencher] Descreva o desafio do cliente.', '[Rascunho — preencher] Descreva a solução desenvolvida.', array[]::text[], null, null, 'draft', 0) on conflict (slug) do nothing;
insert into public.process_steps (title, description, sort_order) values ('Conversa inicial', 'Entendemos a necessidade do seu negócio, seus objetivos e o momento da empresa.', 0);
insert into public.process_steps (title, description, sort_order) values ('Diagnóstico e proposta', 'Definimos juntos o escopo, as entregas e o investimento, de forma clara.', 1);
insert into public.process_steps (title, description, sort_order) values ('Execução', 'Desenvolvemos o projeto ou executamos o planejamento combinado.', 2);
insert into public.process_steps (title, description, sort_order) values ('Acompanhamento', 'Revisamos as entregas, medimos os resultados e planejamos as melhorias.', 3);
insert into public.faqs (question, answer, sort_order) values ('Como funciona a contratação?', 'Tudo começa com uma conversa para entender a sua necessidade. Em seguida enviamos uma proposta com escopo, entregas, prazos e investimento. Com a proposta aprovada, iniciamos o trabalho.', 0);
insert into public.faqs (question, answer, sort_order) values ('Os planos possuem contrato?', 'Sim. Os planos de marketing são formalizados em contrato, com as entregas, o período e as condições combinadas descritas de forma clara.', 1);
insert into public.faqs (question, answer, sort_order) values ('Posso contratar apenas um site?', 'Sim. Os serviços de criação de sites podem ser contratados de forma independente dos planos de marketing.', 2);
insert into public.faqs (question, answer, sort_order) values ('O domínio e a hospedagem estão incluídos?', 'Domínio e hospedagem não estão incluídos por padrão, pois ficam registrados em nome do cliente. Ajudamos na escolha e na configuração, e qualquer custo de terceiros é informado na proposta.', 3);
insert into public.faqs (question, answer, sort_order) values ('Como funciona o desenvolvimento de um sistema personalizado?', 'Fazemos um levantamento de requisitos para entender o seu processo. A partir dele, definimos as funcionalidades, o prazo e o orçamento específico do sistema.', 4);
insert into public.faqs (question, answer, sort_order) values ('Posso solicitar um orçamento sob medida?', 'Sim. Se nenhum plano atende exatamente o que você precisa, montamos uma proposta personalizada.', 5);
insert into public.faqs (question, answer, sort_order) values ('Como funciona a manutenção?', 'A manutenção é um serviço mensal opcional que inclui atualizações, pequenos ajustes e suporte, conforme o escopo combinado.', 6);
